import { isPlatformBrowser } from "@angular/common";
import { computed, DestroyRef, inject, PLATFORM_ID, signal, type Signal } from "@angular/core";
import {
  type ColumnLimits,
  type ColumnWidths,
  parseStoredWidths,
  resetColumnWidth,
  serializeWidths,
  setColumnWidth,
  widthsStorageKey,
} from "@/ui/data-grid/column-widths";

export type ColumnWidthsState = {
  widths: Signal<ColumnWidths>;
  setWidth(id: string, width: number): void;
  resetWidth(id: string): void;
};

// Same-tab writes don't fire the `storage` event, so writers notify here too.
const listeners = new Set<() => void>();

function notify(): void {
  for (const listener of listeners) listener();
}

function readRaw(key: string): string | null {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return null;
  }
}

function writeRaw(key: string, widths: ColumnWidths): boolean {
  try {
    if (Object.keys(widths).length === 0) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, serializeWidths(widths));
    return true;
  } catch {
    return false;
  }
}

/**
 * Column widths the operator chose for one grid, persisted under `pylon.grid.<storageKey>.v1`.
 * Call it in an injection context. On the server (and before storage is readable) the widths
 * are `{}`. `setWidth` and `resetWidth` write through at once; when storage is unavailable or
 * refuses the write, the widths are kept in memory for this page view, so a resize still
 * applies. Other grids with the same key, in this tab or another, pick up the change.
 */
export function columnWidthsState(
  storageKey: Signal<string>,
  columns: Signal<ColumnLimits[]>,
): ColumnWidthsState {
  const browser = isPlatformBrowser(inject(PLATFORM_ID));
  const key = computed(() => widthsStorageKey(storageKey()));
  const version = signal(0);
  // Widths storage refused, for the key they belong to.
  const memory = signal<{ key: string; widths: ColumnWidths } | null>(null);

  if (browser) {
    const bump = () => version.update((v) => v + 1);
    listeners.add(bump);
    window.addEventListener("storage", bump);
    inject(DestroyRef).onDestroy(() => {
      listeners.delete(bump);
      window.removeEventListener("storage", bump);
    });
  }

  const stored = computed(() => {
    version();
    return browser ? parseStoredWidths(readRaw(key()), columns()) : {};
  });

  const widths = computed(() => {
    const held = memory();
    return held && held.key === key() ? held.widths : stored();
  });

  const save = (next: ColumnWidths) => {
    const k = key();
    if (browser && writeRaw(k, next)) {
      memory.set(null);
      notify();
    } else {
      memory.set({ key: k, widths: next });
    }
  };

  return {
    widths,
    setWidth(id, width) {
      const limits = columns().find((c) => c.id === id);
      if (!limits || !Number.isFinite(width)) return;
      save(setColumnWidth(widths(), id, width, limits));
    },
    resetWidth(id) {
      save(resetColumnWidth(widths(), id));
    },
  };
}

export type ColumnLimits = { id: string; minSize: number; maxSize: number };
export type ColumnWidths = Record<string, number>;

export function widthsStorageKey(storageKey: string): string {
  return `pylon.grid.${storageKey}.v1`;
}

export function clampWidth(width: number, limits: ColumnLimits): number {
  return Math.min(limits.maxSize, Math.max(limits.minSize, Math.round(width)));
}

export function parseStoredWidths(raw: string | null, columns: ColumnLimits[]): ColumnWidths {
  if (!raw) return {};
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    return {};
  }
  if (typeof data !== "object" || data === null || Array.isArray(data)) return {};
  const record = data as Record<string, unknown>;
  const out: ColumnWidths = {};
  for (const col of columns) {
    if (!Object.prototype.hasOwnProperty.call(record, col.id)) continue;
    const value = record[col.id];
    if (typeof value !== "number" || !Number.isFinite(value)) continue;
    out[col.id] = clampWidth(value, col);
  }
  return out;
}

export function setColumnWidth(
  widths: ColumnWidths,
  id: string,
  width: number,
  limits: ColumnLimits,
): ColumnWidths {
  return { ...widths, [id]: clampWidth(width, limits) };
}

export function resetColumnWidth(widths: ColumnWidths, id: string): ColumnWidths {
  const { [id]: _removed, ...rest } = widths;
  return rest;
}

export function serializeWidths(widths: ColumnWidths): string {
  return JSON.stringify(widths);
}

import { describe, expect, it } from "vitest";
import {
  clampWidth,
  parseStoredWidths,
  resetColumnWidth,
  serializeWidths,
  setColumnWidth,
  widthsStorageKey,
  type ColumnLimits,
} from "./column-widths";

const name: ColumnLimits = { id: "name", minSize: 48, maxSize: 800 };

describe("widthsStorageKey", () => {
  it("namespaces and versions the key", () => {
    expect(widthsStorageKey("proxmox.guests")).toBe("pylon.grid.proxmox.guests.v1");
  });
});

describe("parseStoredWidths", () => {
  it("reads valid widths", () => {
    expect(parseStoredWidths('{"name":300}', [name])).toEqual({ name: 300 });
  });
  it.each([null, "", "not json", "[1]", "42"])("returns {} for %j", (raw) => {
    expect(parseStoredWidths(raw, [name])).toEqual({});
  });
  it("drops unknown ids", () => {
    expect(parseStoredWidths('{"name":300,"gone":200}', [name])).toEqual({ name: 300 });
  });
  it("drops non-number and non-finite values", () => {
    expect(parseStoredWidths('{"name":"x"}', [name])).toEqual({});
    expect(parseStoredWidths('{"name":1e999}', [name])).toEqual({});
  });
  it("clamps to current limits", () => {
    expect(parseStoredWidths('{"name":10}', [{ ...name, minSize: 160 }])).toEqual({ name: 160 });
    expect(parseStoredWidths('{"name":5000}', [name])).toEqual({ name: 800 });
  });
});

describe("clampWidth", () => {
  it("rounds to an integer", () => {
    expect(clampWidth(200.6, name)).toBe(201);
  });
});

describe("setColumnWidth / resetColumnWidth", () => {
  it("returns a new object with the clamped value", () => {
    const input = { other: 100 };
    const out = setColumnWidth(input, "name", 5000, name);
    expect(out).toEqual({ other: 100, name: 800 });
    expect(input).toEqual({ other: 100 });
  });
  it("reset removes only the key", () => {
    const input = { a: 1, b: 2 };
    expect(resetColumnWidth(input, "a")).toEqual({ b: 2 });
    expect(input).toEqual({ a: 1, b: 2 });
  });
});

describe("serializeWidths", () => {
  it("serializes as JSON", () => {
    expect(serializeWidths({ a: 1 })).toBe('{"a":1}');
  });
});

/**
 * How many chips fit on one line. When some chips are hidden, room for the
 * "+N" chip (and the gap before it) is reserved.
 */
export function fitChipCount(
  chipWidths: number[],
  available: number,
  plusWidth: number,
  gap: number,
): number {
  const total = chipWidths.length;
  let used = 0;
  let best = 0;
  for (let n = 1; n <= total; n++) {
    used += chipWidths[n - 1] + (n > 1 ? gap : 0);
    const needed = n < total ? used + gap + plusWidth : used;
    if (needed <= available) best = n;
  }
  return best;
}

/** Accessible name for the "+N" chip that opens the hidden tags. */
export function moreTagsLabel(hidden: number): string {
  return `Show ${hidden} more ${hidden === 1 ? "tag" : "tags"}`;
}

import { describe, expect, it } from "vitest";
import { fitChipCount, moreTagsLabel } from "./chip-fit";

describe("fitChipCount", () => {
  it("fits all chips when there is room", () => {
    expect(fitChipCount([50, 50, 50], 200, 24, 4)).toBe(3);
  });
  it("reserves room for the +N chip when some are hidden", () => {
    expect(fitChipCount([50, 50, 50], 120, 24, 4)).toBe(1);
  });
  it("needs no plus chip when everything fits", () => {
    expect(fitChipCount([50], 50, 24, 4)).toBe(1);
  });
  it("returns 0 when not even one chip plus the counter fits", () => {
    expect(fitChipCount([50, 50], 20, 24, 4)).toBe(0);
  });
  it("returns 0 for no chips", () => {
    expect(fitChipCount([], 100, 24, 4)).toBe(0);
  });
  it("accepts the exact boundary", () => {
    expect(fitChipCount([50, 50], 104, 24, 4)).toBe(2);
  });
});

describe("moreTagsLabel", () => {
  it("pluralises the hidden-tag count", () => {
    expect(moreTagsLabel(4)).toBe("Show 4 more tags");
    expect(moreTagsLabel(1)).toBe("Show 1 more tag");
  });
});

import {
  afterRenderEffect,
  ChangeDetectionStrategy,
  Component,
  computed,
  DestroyRef,
  ElementRef,
  inject,
  input,
  signal,
  viewChild,
} from "@angular/core";
import { KoPopover, KoPopoverContent, KoPopoverTrigger } from "@/ui/primitives/popover.component";
import { cn } from "@/ui/utils";
import { fitChipCount, moreTagsLabel } from "./chip-fit";

export type ChipColor = { bg: string; fg: string };

export const CHIP = "max-w-40 truncate rounded px-1.5 py-0.5 text-[10px] font-medium";

/** Used when no `color` is given. */
const NEUTRAL_CHIP = "bg-secondary text-secondary-foreground";

const GAP = 4; // matches gap-1

const FOCUS_RING =
  "cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring";

/** One tag. With `onSelect` it is a button (its click and keydown stay inside); otherwise a span. */
@Component({
  selector: "ko-chip",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `
    @if (onSelect(); as select) {
      <button
        type="button"
        [class]="buttonClass()"
        [style.background-color]="color()?.bg ?? null"
        [style.color]="color()?.fg ?? null"
        [title]="tag()"
        (keydown)="$event.stopPropagation()"
        (click)="$event.stopPropagation(); select(tag())"
      >
        {{ tag() }}
      </button>
    } @else {
      <span
        [class]="spanClass()"
        [style.background-color]="color()?.bg ?? null"
        [style.color]="color()?.fg ?? null"
        [title]="tag()"
        >{{ tag() }}</span
      >
    }
  `,
})
export class KoChip {
  readonly tag = input.required<string>();
  readonly color = input<ChipColor>();
  readonly onSelect = input<(tag: string) => void>();
  readonly class = input<string>("");

  private readonly base = computed(() => (this.color() ? CHIP : cn(CHIP, NEUTRAL_CHIP)));
  protected readonly buttonClass = computed(() => cn(this.base(), this.class(), FOCUS_RING));
  protected readonly spanClass = computed(() => cn(this.base(), this.class()));
}

/**
 * One non-wrapping line: as many chips as fit, plus a "+N" button that opens a popover listing
 * the rest. The "+N" click and keydown stop propagation; the popover is in an overlay, so clicks
 * inside it never reach a row.
 */
@Component({
  selector: "ko-chip-list",
  imports: [KoChip, KoPopover, KoPopoverContent, KoPopoverTrigger],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "hostClass()" },
  template: `
    <span class="flex min-w-0 flex-nowrap items-center gap-1 overflow-hidden">
      @for (tag of shown(); track tag) {
        <ko-chip [tag]="tag" [color]="color()?.(tag)" [onSelect]="onSelect()" class="shrink-0" />
      }
      @if (hidden().length > 0) {
        <button
          type="button"
          [attr.aria-label]="moreLabel()"
          [class]="moreClass"
          [koPopoverTrigger]="more"
          (keydown)="$event.stopPropagation()"
          (click)="$event.stopPropagation()"
        >
          +{{ hidden().length }}
        </button>
        <ko-popover #more [(open)]="moreOpen">
          <ng-template koPopoverContent>
            <div class="flex max-w-80 flex-wrap gap-1 p-0.5">
              @for (tag of hidden(); track tag) {
                <ko-chip [tag]="tag" [color]="color()?.(tag)" [onSelect]="popoverSelect()" />
              }
            </div>
          </ng-template>
        </ko-popover>
      }
    </span>
    <span
      #measure
      aria-hidden="true"
      class="pointer-events-none invisible absolute top-0 left-0 flex flex-nowrap gap-1 whitespace-nowrap"
    >
      @for (tag of list(); track tag) {
        <span [class]="chip" [title]="tag" tabindex="-1">{{ tag }}</span>
      }
      <span [class]="chip">+{{ list().length }}</span>
    </span>
  `,
})
export class KoChipList {
  readonly tags = input<string[] | null | undefined>([]);
  readonly color = input<(tag: string) => ChipColor>();
  readonly onSelect = input<(tag: string) => void>();
  readonly class = input<string>("");

  protected readonly chip = CHIP;
  protected readonly moreClass = cn(CHIP, "shrink-0 bg-muted text-muted-foreground", FOCUS_RING);
  protected readonly moreOpen = signal(false);
  protected readonly list = computed(() => this.tags() ?? []);
  /** null = not measured yet (SSR / first paint): render all chips, clipped. */
  private readonly count = signal<number | null>(null);
  protected readonly shown = computed(() => this.list().slice(0, this.fitted()));
  protected readonly hidden = computed(() => this.list().slice(this.fitted()));
  protected readonly moreLabel = computed(() => moreTagsLabel(this.hidden().length));
  protected readonly hostClass = computed(() =>
    cn("relative flex min-w-0 overflow-hidden", this.class()),
  );
  protected readonly popoverSelect = computed(() => {
    const select = this.onSelect();
    if (!select) return undefined;
    return (tag: string) => {
      this.moreOpen.set(false);
      select(tag);
    };
  });

  private readonly fitted = computed(() => {
    const count = this.count();
    const total = this.list().length;
    return count === null ? total : Math.min(count, total);
  });
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly measureRef = viewChild.required<ElementRef<HTMLElement>>("measure");

  constructor() {
    let observer: ResizeObserver | undefined;
    afterRenderEffect(() => {
      this.list();
      const wrap = this.host.nativeElement;
      const measure = this.measureRef().nativeElement;
      if (typeof ResizeObserver === "undefined") return;
      const run = () => {
        const kids = Array.from(measure.children) as HTMLElement[];
        const plus = kids.pop();
        const widths = kids.map((k) => k.offsetWidth);
        this.count.set(fitChipCount(widths, wrap.clientWidth, plus?.offsetWidth ?? 0, GAP));
      };
      observer?.disconnect();
      // Fires once on observe, which also covers the initial measure and re-measure on tags change.
      observer = new ResizeObserver(run);
      observer.observe(wrap);
    });
    inject(DestroyRef).onDestroy(() => observer?.disconnect());
  }
}

import { flexRenderComponent } from "@tanstack/angular-table";
import type { Breakpoint, DataGridColumn } from "@/ui/data-grid/types";
import { type ChipColor, KoChipList } from "./chip-list.component";
import { KoProgressCell } from "./progress-cell.component";
import type { ProgressVariant } from "./progress-level";
import { KoStatusCell } from "./status-cell.component";
import type { StatusTone } from "./tones";

export type ProgressValue = { percent: number; label: string };

export function progressColumn<T>(opts: {
  id: string;
  header: string;
  size: number;
  minSize?: number;
  /** `null` renders the empty 0% bar. */
  value: (row: T) => ProgressValue | null;
  variant: ProgressVariant;
  /** When set, the bar gets this `title`. */
  title?: (row: T) => string | undefined;
  sortValue?: (row: T) => number | null;
  className?: string;
  headerClassName?: string;
  hideBelow?: Breakpoint;
}): DataGridColumn<T> {
  const { value, variant, title } = opts;
  return {
    id: opts.id,
    header: opts.header,
    size: opts.size,
    minSize: opts.minSize,
    sortValue: opts.sortValue,
    className: opts.className,
    headerClassName: opts.headerClassName,
    hideBelow: opts.hideBelow,
    cell: (row) => {
      const v = value(row);
      return flexRenderComponent(KoProgressCell, {
        inputs: {
          percent: v ? v.percent : 0,
          label: v ? v.label : "0%",
          variant,
          title: title?.(row),
        },
      });
    },
  };
}

export function statusColumn<T>(opts: {
  id: string;
  header: string;
  size: number;
  minSize?: number;
  status: (row: T) => string;
  tone: (status: string) => StatusTone;
  style: "badge" | "dot";
  /** Defaults to the raw status string. */
  label?: (status: string) => string;
  /** Sort by the raw status string. Default false. */
  sortable?: boolean;
  className?: string;
  headerClassName?: string;
  hideBelow?: Breakpoint;
}): DataGridColumn<T> {
  const { status, tone, style, label } = opts;
  return {
    id: opts.id,
    header: opts.header,
    size: opts.size,
    minSize: opts.minSize,
    sortValue: opts.sortable ? status : undefined,
    className: opts.className,
    headerClassName: opts.headerClassName,
    hideBelow: opts.hideBelow,
    cell: (row) => {
      const s = status(row);
      return flexRenderComponent(KoStatusCell, {
        inputs: { tone: tone(s), label: label ? label(s) : s, style },
      });
    },
  };
}

export function tagsColumn<T>(opts: {
  id: string;
  header: string;
  size: number;
  minSize?: number;
  tags: (row: T) => string[];
  color?: (tag: string) => ChipColor;
  onSelect?: (tag: string) => void;
  className?: string;
  headerClassName?: string;
  hideBelow?: Breakpoint;
}): DataGridColumn<T> {
  const { tags, color, onSelect } = opts;
  return {
    id: opts.id,
    header: opts.header,
    size: opts.size,
    minSize: opts.minSize,
    className: opts.className,
    headerClassName: opts.headerClassName,
    hideBelow: opts.hideBelow,
    cell: (row) =>
      flexRenderComponent(KoChipList, { inputs: { tags: tags(row), color, onSelect } }),
  };
}

import { ChangeDetectionStrategy, Component, computed, input } from "@angular/core";
import { cn } from "@/ui/utils";
import { metricBarLabelClass, usageBarFillClass, type ProgressVariant } from "./progress-level";

/** A usage bar with its label centred on it. `title` lands on the host (the bar's wrapper). */
@Component({
  selector: "ko-progress-cell",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    class: "relative block h-6 w-full overflow-hidden rounded-sm bg-secondary/90",
    "[attr.title]": "title() ?? null",
  },
  template: `
    <div [class]="fillClass()" [style.width.%]="width()"></div>
    <div [class]="labelClass()" [attr.title]="label()">{{ label() }}</div>
  `,
})
export class KoProgressCell {
  readonly percent = input.required<number>();
  readonly label = input.required<string>();
  readonly variant = input<ProgressVariant>("cpu");
  readonly title = input<string>();

  protected readonly width = computed(() => Math.min(100, Math.max(0, this.percent())));
  protected readonly fillClass = computed(() =>
    cn(
      "absolute inset-y-0 left-0 transition-[width] duration-300",
      usageBarFillClass(this.percent(), this.variant()),
    ),
  );
  protected readonly labelClass = computed(() =>
    cn(
      "relative z-10 flex h-full items-center justify-center px-2 text-[10px] tabular-nums",
      "truncate",
      metricBarLabelClass(this.percent(), this.width()),
    ),
  );
}

export type ProgressVariant = "cpu" | "memory" | "disk";

export function usageLevel(percent: number): "ok" | "warn" | "critical" {
  if (percent >= 90) return "critical";
  if (percent >= 75) return "warn";
  return "ok";
}

export function usageBarFillClass(percent: number, kind: ProgressVariant): string {
  const level = usageLevel(percent);
  if (level === "critical") return "bg-destructive";
  if (level === "warn") return "bg-amber-500";
  if (kind === "cpu") return "bg-foreground/65";
  return "bg-emerald-500";
}

export function metricBarLabelClass(percent: number, fillWidth: number): string {
  if (fillWidth <= 0) return "text-muted-foreground";
  const level = usageLevel(percent);
  if (level !== "ok" && fillWidth >= 28) {
    return "font-medium text-white drop-shadow-[0_1px_1px_rgba(0,0,0,0.75)]";
  }
  return "text-foreground";
}

import { describe, expect, it } from "vitest";
import { usageBarFillClass, metricBarLabelClass, usageLevel } from "./progress-level";

describe("usageLevel", () => {
  it("is ok below 75", () => {
    expect(usageLevel(0)).toBe("ok");
    expect(usageLevel(74.9)).toBe("ok");
  });
  it("is warn from 75 up to 90", () => {
    expect(usageLevel(75)).toBe("warn");
    expect(usageLevel(89.9)).toBe("warn");
  });
  it("is critical from 90", () => {
    expect(usageLevel(90)).toBe("critical");
    expect(usageLevel(100)).toBe("critical");
  });
});

describe("usageBarFillClass", () => {
  it("uses the destructive fill when critical, for every variant", () => {
    for (const v of ["cpu", "memory", "disk"] as const) {
      expect(usageBarFillClass(95, v)).toBe("bg-destructive");
    }
  });
  it("uses the amber fill when warn, for every variant", () => {
    for (const v of ["cpu", "memory", "disk"] as const) {
      expect(usageBarFillClass(80, v)).toBe("bg-amber-500");
    }
  });
  it("uses a neutral fill for cpu and emerald for memory and disk when ok", () => {
    expect(usageBarFillClass(10, "cpu")).toBe("bg-foreground/65");
    expect(usageBarFillClass(10, "memory")).toBe("bg-emerald-500");
    expect(usageBarFillClass(10, "disk")).toBe("bg-emerald-500");
  });
});

describe("metricBarLabelClass", () => {
  it("is muted when the bar is empty", () => {
    expect(metricBarLabelClass(0, 0)).toBe("text-muted-foreground");
  });
  it("is white with a shadow over a wide warn or critical fill", () => {
    const white = "font-medium text-white drop-shadow-[0_1px_1px_rgba(0,0,0,0.75)]";
    expect(metricBarLabelClass(80, 80)).toBe(white);
    expect(metricBarLabelClass(95, 28)).toBe(white);
  });
  it("is foreground for an ok fill or a narrow warn fill", () => {
    expect(metricBarLabelClass(50, 50)).toBe("text-foreground");
    expect(metricBarLabelClass(95, 27)).toBe("text-foreground");
  });
});

import { ChangeDetectionStrategy, Component, computed, input } from "@angular/core";
import { KoBadge } from "@/ui/primitives/badge.component";
import { cn } from "@/ui/utils";
import { BADGE_VARIANT, DOT_CLASS, TEXT_CLASS, type StatusTone } from "./tones";

/** A status as a badge in its tone's variant; the label is the projected content. */
@Component({
  selector: "ko-tone-badge",
  imports: [KoBadge],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `<ko-badge [variant]="variant()"><ng-content /></ko-badge>`,
})
export class KoToneBadge {
  readonly tone = input.required<StatusTone>();
  protected readonly variant = computed(() => BADGE_VARIANT[this.tone()]);
}

/** A status as a coloured dot and label; the label is the projected content. */
@Component({
  selector: "ko-status-dot-label",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "flex items-center gap-2" },
  template: `
    <span [class]="dotClass()"></span>
    <span [class]="textClass()"><ng-content /></span>
  `,
})
export class KoStatusDotLabel {
  readonly tone = input.required<StatusTone>();
  protected readonly dotClass = computed(() => cn("size-2 rounded-full", DOT_CLASS[this.tone()]));
  protected readonly textClass = computed(() => cn("capitalize", TEXT_CLASS[this.tone()]));
}

/** The `statusColumn` cell: `label` as a badge or a dot label, in `tone`. */
@Component({
  selector: "ko-status-cell",
  imports: [KoToneBadge, KoStatusDotLabel],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "contents" },
  template: `
    @if (style() === "badge") {
      <ko-tone-badge [tone]="tone()">{{ label() }}</ko-tone-badge>
    } @else {
      <ko-status-dot-label [tone]="tone()">{{ label() }}</ko-status-dot-label>
    }
  `,
})
export class KoStatusCell {
  readonly tone = input.required<StatusTone>();
  readonly label = input.required<string>();
  readonly style = input<"badge" | "dot">("badge");
}

export type StatusTone = "live" | "success" | "warning" | "danger" | "muted" | "neutral";

export const BADGE_VARIANT = {
  live: "live",
  success: "live",
  warning: "warn",
  danger: "danger",
  muted: "outline",
  neutral: "default",
} as const satisfies Record<StatusTone, "live" | "warn" | "danger" | "outline" | "default">;

/** Dot fill per tone (matches the Docker panel's container state dot). */
export const DOT_CLASS: Record<StatusTone, string> = {
  success: "bg-emerald-500",
  live: "bg-emerald-500",
  warning: "bg-amber-500",
  danger: "bg-destructive",
  muted: "bg-muted-foreground/50",
  neutral: "bg-muted-foreground",
};

/** Label colour per tone (matches the Docker panel's container state text). */
export const TEXT_CLASS: Record<StatusTone, string> = {
  success: "text-emerald-600 dark:text-emerald-400",
  live: "text-emerald-600 dark:text-emerald-400",
  warning: "text-amber-600 dark:text-amber-400",
  danger: "text-destructive",
  muted: "text-muted-foreground",
  neutral: "text-foreground",
};

import { describe, expect, it } from "vitest";
import { BADGE_VARIANT, DOT_CLASS, TEXT_CLASS, type StatusTone } from "./tones";

const TONES: StatusTone[] = ["live", "success", "warning", "danger", "muted", "neutral"];

describe("status tones", () => {
  it("maps every tone to a badge variant", () => {
    expect(BADGE_VARIANT).toEqual({
      live: "live",
      success: "live",
      warning: "warn",
      danger: "danger",
      muted: "outline",
      neutral: "default",
    });
  });

  it("maps every tone to a dot class", () => {
    expect(DOT_CLASS).toEqual({
      success: "bg-emerald-500",
      live: "bg-emerald-500",
      warning: "bg-amber-500",
      danger: "bg-destructive",
      muted: "bg-muted-foreground/50",
      neutral: "bg-muted-foreground",
    });
  });

  it("maps every tone to a text class", () => {
    expect(TEXT_CLASS).toEqual({
      success: "text-emerald-600 dark:text-emerald-400",
      live: "text-emerald-600 dark:text-emerald-400",
      warning: "text-amber-600 dark:text-amber-400",
      danger: "text-destructive",
      muted: "text-muted-foreground",
      neutral: "text-foreground",
    });
  });

  it("covers exactly the StatusTone values", () => {
    for (const map of [BADGE_VARIANT, DOT_CLASS, TEXT_CLASS]) {
      expect(Object.keys(map).sort()).toEqual([...TONES].sort());
    }
  });
});

import { isPlatformBrowser, NgTemplateOutlet } from "@angular/common";
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  DestroyRef,
  Directive,
  inject,
  input,
  output,
  PLATFORM_ID,
  signal,
  TemplateRef,
} from "@angular/core";
import { outputFromObservable } from "@angular/core/rxjs-interop";
import { NgIcon } from "@ng-icons/core";
import { lucideArrowDown, lucideArrowUp, lucideLoaderCircle } from "@ng-icons/lucide";
import {
  columnPinningFeature,
  columnResizingFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  createSortedRowModel,
  FlexRender,
  injectTable,
  rowSortingFeature,
  tableFeatures,
  type ColumnDef,
  type RowData,
} from "@tanstack/angular-table";
import { Observable, Subject } from "rxjs";
import { columnWidthsState } from "@/ui/data-grid/column-widths-state";
import {
  BREAKPOINT_PX,
  compareSortValues,
  headerSelectionState,
  isInteractiveTarget,
  pinnedOffsets,
  selectRange,
  toggleAll,
  toggleSelection,
  visibleColumnIds,
} from "@/ui/data-grid/grid-layout";
import { KoResizeHandle } from "@/ui/data-grid/resize-handle.component";
import type { CellContent, DataGridClassNames, DataGridColumn } from "@/ui/data-grid/types";
import { KoCheckbox, type KoCheckedState } from "@/ui/primitives/checkbox.component";
import { cn } from "@/ui/utils";

const DEFAULT_MIN = 48;
const DEFAULT_MAX = 800;

/** Id of the synthetic checkbox column added by the `selection` input. */
const SELECT_COLUMN_ID = "__select";
const SELECT_COLUMN_SIZE = 40;

const PINNED_SHADOW = "shadow-[4px_0_6px_-4px_rgb(0_0_0/0.6)]";

const features = tableFeatures({
  columnSizingFeature,
  columnResizingFeature,
  columnPinningFeature,
  columnVisibilityFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
});

type Features = typeof features;
type SortKey = string | number | undefined;

const BREAKPOINT_QUERIES = (["xl", "lg", "md", "sm"] as const).map((bp) => ({
  width: BREAKPOINT_PX[bp],
  query: `(min-width: ${BREAKPOINT_PX[bp]}px)`,
}));

/** On the server, or without `matchMedia`: assume the desktop table with every column. */
const SSR_VIEWPORT_WIDTH = BREAKPOINT_PX.xl;

function viewportSnapshot(): number {
  for (const b of BREAKPOINT_QUERIES) if (window.matchMedia(b.query).matches) return b.width;
  return 0;
}

type RowContext<T> = { $implicit: T };

/** `<ng-template koGridMobileCard let-row>`: below `md`, one card per row replaces the table. */
@Directive({ selector: "ng-template[koGridMobileCard]" })
export class KoGridMobileCard<T> {
  /** Optional: bind the grid's rows (`[koGridMobileCard]="rows"`) to type `let-row`. */
  readonly koGridMobileCard = input<readonly T[] | "">("");
  readonly template = inject<TemplateRef<RowContext<T>>>(TemplateRef);

  static ngTemplateContextGuard<T>(
    _dir: KoGridMobileCard<T>,
    _ctx: unknown,
  ): _ctx is RowContext<T> {
    return true;
  }
}

/** `<ng-template koGridRowDetail let-row>`: a full-width row after each record's row. */
@Directive({ selector: "ng-template[koGridRowDetail]" })
export class KoGridRowDetail<T> {
  /** Optional: bind the grid's rows (`[koGridRowDetail]="rows"`) to type `let-row`. */
  readonly koGridRowDetail = input<readonly T[] | "">("");
  readonly template = inject<TemplateRef<RowContext<T>>>(TemplateRef);

  static ngTemplateContextGuard<T>(_dir: KoGridRowDetail<T>, _ctx: unknown): _ctx is RowContext<T> {
    return true;
  }
}

/** `<ng-template koGridEmpty>`: what an empty grid shows. */
@Directive({ selector: "ng-template[koGridEmpty]" })
export class KoGridEmpty {
  readonly template = inject<TemplateRef<unknown>>(TemplateRef);
}

type HeaderView<T> = {
  id: string;
  column: DataGridColumn<T>;
  select: boolean;
  className: string;
  left: number | null;
  size: number;
  text: string | null;
  template: TemplateRef<unknown> | null;
  sortable: boolean;
  sorted: false | "asc" | "desc";
  ariaSort: "ascending" | "descending" | "none" | null;
  toggleSort: ((event: unknown) => void) | undefined;
  showHandle: boolean;
  minSize: number;
  maxSize: number;
  label: string;
};

type CellView<T> = {
  id: string;
  select: boolean;
  className: string;
  left: number | null;
  title: string | null;
  cell: (row: T) => CellContent<T>;
};

type RowView<T> = {
  id: string;
  original: T;
  selected: boolean;
  className: string;
  cells: CellView<T>[];
  detail: boolean;
};

/**
 * One table component for every record list: column widths remembered per `storageKey`, pinned
 * and sortable columns, breakpoint-hidden columns, opt-in selection, detail rows and mobile
 * cards. Built on `@tanstack/angular-table`; cells render through `FlexRender`. The full
 * contract (inputs, outputs and templates) is documented on `DataGridProps` in `types.ts`.
 */
@Component({
  selector: "ko-data-grid",
  imports: [NgTemplateOutlet, NgIcon, FlexRender, KoCheckbox, KoResizeHandle],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { "[class]": "'contents'" },
  templateUrl: "./data-grid.component.html",
})
export class KoDataGrid<T extends RowData> {
  readonly storageKey = input.required<string>();
  readonly rows = input.required<readonly T[]>();
  readonly getRowId = input.required<(row: T) => string>();
  readonly columns = input.required<DataGridColumn<T>[]>();
  readonly layout = input<"auto" | "fixed">("auto");
  readonly resizable = input(false, { transform: booleanAttribute });
  readonly stickyHeader = input(false, { transform: booleanAttribute });
  readonly loading = input(false, { transform: booleanAttribute });
  readonly emptyRow = input(false, { transform: booleanAttribute });
  readonly classNames = input<DataGridClassNames<T>>();
  readonly class = input<string>("");
  /** Selected `getRowId` values. Selection is on whenever this is bound to a set. */
  readonly selection = input<ReadonlySet<string>>();
  readonly selectionLabel = input<(row: T) => string>();
  readonly hasRowDetail = input<(row: T) => boolean>();

  private readonly rowClicks = new Subject<T>();
  /** Listeners on `rowClick`; rows are styled clickable only when someone listens. */
  private rowClickListeners = 0;
  readonly rowClick = outputFromObservable<T>(
    new Observable<T>((subscriber) => {
      this.rowClickListeners++;
      const subscription = this.rowClicks.subscribe(subscriber);
      return () => {
        subscription.unsubscribe();
        this.rowClickListeners--;
      };
    }),
  );
  readonly rowDoubleClick = output<T>();
  readonly rowContextMenu = output<{ row: T; event: MouseEvent }>();
  readonly selectionChange = output<Set<string>>();

  protected readonly mobileCard = contentChild<KoGridMobileCard<T>>(KoGridMobileCard);
  protected readonly rowDetail = contentChild<KoGridRowDetail<T>>(KoGridRowDetail);
  protected readonly empty = contentChild(KoGridEmpty);

  protected readonly spinner = lucideLoaderCircle;
  protected readonly arrowUp = lucideArrowUp;
  protected readonly arrowDown = lucideArrowDown;

  /** Viewport width bucketed to Tailwind's breakpoints (0/640/768/1024/1280). */
  private readonly viewportWidth = signal(SSR_VIEWPORT_WIDTH);
  /** Last row toggled by a row checkbox; Shift+click selects from here. */
  private anchor: string | null = null;

  protected readonly fixed = computed(() => this.layout() === "fixed");
  private readonly canResize = computed(() => this.fixed() && this.resizable());
  protected readonly hasSelection = computed(() => this.selection() !== undefined);
  protected readonly isDesktop = computed(() => this.viewportWidth() >= BREAKPOINT_PX.md);

  /** Without `selection` this is the caller's array as-is. */
  private readonly allColumns = computed<DataGridColumn<T>[]>(() => {
    const callerColumns = this.columns();
    if (!this.hasSelection()) return callerColumns;
    const anyPinned = callerColumns.some((c) => c.pinned === "left");
    const selectColumn: DataGridColumn<T> = {
      id: SELECT_COLUMN_ID,
      header: "",
      cell: () => null,
      size: SELECT_COLUMN_SIZE,
      minSize: SELECT_COLUMN_SIZE,
      maxSize: SELECT_COLUMN_SIZE,
      resizable: false,
      ...(anyPinned ? { pinned: "left" as const } : {}),
      className: "w-10 px-3",
      headerClassName: "w-10 px-3",
    };
    return [selectColumn, ...callerColumns];
  });

  private readonly limits = computed(() =>
    this.allColumns().map((c) => ({
      id: c.id,
      minSize: c.minSize ?? DEFAULT_MIN,
      maxSize: c.maxSize ?? DEFAULT_MAX,
    })),
  );
  private readonly widths = columnWidthsState(this.storageKey, this.limits);

  private readonly byId = computed(() => new Map(this.allColumns().map((c) => [c.id, c])));

  private readonly columnDefs = computed<ColumnDef<Features, T, unknown>[]>(() =>
    this.allColumns().map((c) => {
      const sortValue = c.sortValue;
      const base = {
        id: c.id,
        size: c.size,
        minSize: c.minSize ?? DEFAULT_MIN,
        maxSize: c.maxSize ?? DEFAULT_MAX,
        enableResizing: c.resizable !== false,
        enablePinning: c.pinned === "left",
        enableSorting: !!sortValue,
      };
      if (!sortValue) return base;
      return {
        ...base,
        // Nulls map to undefined so `sortUndefined: "last"` keeps them at the
        // end in both directions (it is applied before the desc flip).
        accessorFn: (row: T) => sortValue(row) ?? undefined,
        sortUndefined: "last" as const,
        sortDescFirst: false,
        sortFn: (
          a: { getValue<V>(id: string): V },
          b: { getValue<V>(id: string): V },
          id: string,
        ) =>
          compareSortValues(
            a.getValue<SortKey>(id) ?? null,
            b.getValue<SortKey>(id) ?? null,
            false,
          ),
      } as ColumnDef<Features, T, unknown>;
    }),
  );

  private readonly columnVisibility = computed(() => {
    const columns = this.allColumns();
    const visible = new Set(visibleColumnIds(columns, this.viewportWidth()));
    const out: Record<string, boolean> = {};
    for (const c of columns) out[c.id] = visible.has(c.id);
    return out;
  });

  private readonly columnPinning = computed(() => ({
    start: this.allColumns()
      .filter((c) => c.pinned === "left")
      .map((c) => c.id),
    end: [],
  }));

  private readonly table = injectTable<Features, T>(() => ({
    features,
    data: this.rows(),
    columns: this.columnDefs(),
    getRowId: (row: T) => this.getRowId()(row),
    enableColumnResizing: this.canResize(),
    enableMultiSort: false,
    state: {
      columnSizing: this.canResize() ? this.widths.widths() : {},
      columnVisibility: this.columnVisibility(),
      columnPinning: this.columnPinning(),
    },
  }));

  protected readonly sortedRows = computed(() => this.table.getRowModel().rows);

  protected readonly emptyInTable = computed(
    () => this.emptyRow() && (this.isDesktop() || !this.mobileCard()),
  );
  protected readonly emptyAlone = computed(
    () => this.rows().length === 0 && !!this.empty() && !this.emptyInTable(),
  );
  protected readonly emptyInBody = computed(
    () => this.rows().length === 0 && !!this.empty() && this.emptyInTable(),
  );
  protected readonly showCards = computed(() => !this.isDesktop() && !!this.mobileCard());

  // Header order already puts pinned columns first.
  private readonly tableHeaders = computed(() => this.table.getHeaderGroups()[0]?.headers ?? []);
  protected readonly sizes = computed(() => {
    const out: Record<string, number> = {};
    for (const h of this.tableHeaders()) out[h.column.id] = h.column.getSize();
    return out;
  });
  private readonly offsets = computed(() =>
    pinnedOffsets(
      this.tableHeaders().map((h) => ({
        id: h.column.id,
        pinned: this.byId().get(h.column.id)?.pinned,
      })),
      this.sizes(),
    ),
  );
  private readonly lastPinned = computed(() => Object.keys(this.offsets()).at(-1));
  protected readonly totalWidth = computed(() =>
    this.tableHeaders().reduce((sum, h) => sum + this.sizes()[h.column.id]!, 0),
  );
  protected readonly needsWrapper = computed(
    () => !!this.class() || this.fixed() || Object.keys(this.offsets()).length > 0,
  );
  protected readonly wrapperClass = computed(() => cn("overflow-x-auto", this.class()));

  protected readonly headers = computed<HeaderView<T>[]>(() => {
    const offsets = this.offsets();
    const sizes = this.sizes();
    const sticky = this.stickyHeader();
    const headerCell = this.classNames()?.headerCell;
    const out: HeaderView<T>[] = [];
    for (const h of this.tableHeaders()) {
      const col = this.byId().get(h.column.id);
      if (!col) continue;
      const id = col.id;
      const pinned = id in offsets;
      const select = id === SELECT_COLUMN_ID && this.hasSelection();
      const sortable = !select && h.column.getCanSort();
      const sorted = sortable ? h.column.getIsSorted() : false;
      const showHandle = !select && this.canResize() && h.column.getCanResize();
      out.push({
        id: h.id,
        column: col,
        select,
        className: cn(
          "relative",
          !select && col.align === "right" && "text-right",
          showHandle && "group/header",
          (sticky || pinned) && "bg-background",
          sticky && "sticky top-0 z-20",
          pinned && "sticky z-30",
          id === this.lastPinned() && PINNED_SHADOW,
          headerCell,
          col.headerClassName,
        ),
        left: pinned ? offsets[id]! : null,
        size: sizes[id]!,
        text: typeof col.header === "string" ? col.header : null,
        template: typeof col.header === "string" ? null : col.header,
        sortable,
        sorted,
        ariaSort: sortable
          ? sorted === "asc"
            ? "ascending"
            : sorted === "desc"
              ? "descending"
              : "none"
          : null,
        toggleSort: sortable ? h.column.getToggleSortingHandler() : undefined,
        showHandle,
        minSize: col.minSize ?? DEFAULT_MIN,
        maxSize: col.maxSize ?? DEFAULT_MAX,
        label: typeof col.header === "string" ? col.header : id,
      });
    }
    return out;
  });

  protected readonly bodyRows = computed<RowView<T>[]>(() => {
    const offsets = this.offsets();
    const selected = this.selection();
    const classNames = this.classNames();
    const clickable = this.rowClickListeners > 0;
    const detail = this.rowDetail();
    const hasRowDetail = this.hasRowDetail();
    const columns = this.headers().map((h) => h.column);
    return this.sortedRows().map((row) => {
      const original = row.original;
      const rowClass =
        typeof classNames?.row === "function" ? classNames.row(original) : classNames?.row;
      return {
        id: row.id,
        original,
        selected: selected?.has(row.id) ?? false,
        className: cn(rowClass, clickable && "group cursor-pointer hover:bg-secondary/40"),
        detail: !!detail && (hasRowDetail ? hasRowDetail(original) : true),
        cells: columns.map((col) => {
          const pinned = col.id in offsets;
          const extra = col.cellProps?.(original);
          return {
            id: `${row.id}_${col.id}`,
            select: col.id === SELECT_COLUMN_ID && !!selected,
            left: pinned ? offsets[col.id]! : null,
            title: extra?.title ?? null,
            cell: col.cell,
            className: cn(
              col.align === "right" && "text-right",
              pinned
                ? cn(
                    "sticky z-10 bg-background",
                    clickable && "group-hover:bg-grid-pinned-hover",
                    col.id === this.lastPinned() && PINNED_SHADOW,
                  )
                : "isolate",
              classNames?.cell,
              col.className,
              extra?.className,
            ),
          };
        }),
      };
    });
  });

  private readonly allIds = computed(() => {
    const getRowId = this.getRowId();
    return this.hasSelection() ? this.rows().map(getRowId) : [];
  });
  protected readonly headerChecked = computed<KoCheckedState>(() => {
    const state = headerSelectionState(this.selection() ?? new Set(), this.allIds());
    return state === "all" ? true : state === "some" ? "indeterminate" : false;
  });

  constructor() {
    if (isPlatformBrowser(inject(PLATFORM_ID)) && typeof window.matchMedia === "function") {
      const read = () => this.viewportWidth.set(viewportSnapshot());
      read();
      const lists = BREAKPOINT_QUERIES.map((b) => window.matchMedia(b.query));
      for (const mq of lists) mq.addEventListener?.("change", read);
      inject(DestroyRef).onDestroy(() => {
        for (const mq of lists) mq.removeEventListener?.("change", read);
      });
    }
  }

  protected rowLabel(row: RowView<T>): string {
    return this.selectionLabel()?.(row.original) ?? `Select ${row.id}`;
  }

  protected setWidth(id: string, width: number): void {
    this.widths.setWidth(id, width);
  }

  protected resetWidth(id: string): void {
    this.widths.resetWidth(id);
  }

  protected onRowClick(row: T, event: MouseEvent): void {
    if (this.rowClickListeners === 0) return;
    if (isInteractiveTarget(event.target as Element, event.currentTarget as Element)) return;
    this.rowClicks.next(row);
  }

  protected onRowDoubleClick(row: T, event: MouseEvent): void {
    if (isInteractiveTarget(event.target as Element, event.currentTarget as Element)) return;
    this.rowDoubleClick.emit(row);
  }

  protected onRowContextMenu(row: T, event: MouseEvent): void {
    if (!(event.currentTarget as Element).contains(event.target as Node)) return;
    this.rowContextMenu.emit({ row, event });
  }

  protected onToggleAll(box: KoCheckbox): void {
    // The checkbox toggled itself; it shows `selection` until the caller applies the change.
    box.checked.set(this.headerChecked());
    const selected = this.selection();
    if (!selected) return;
    this.selectionChange.emit(toggleAll(selected, this.allIds()));
  }

  /**
   * The whole cell is a click target so a near-miss on the 16px box doesn't open the row.
   * A click on the checkbox bubbles here too, after the checkbox toggled itself.
   */
  protected onSelectCellClick(row: RowView<T>, box: KoCheckbox, event: MouseEvent): void {
    box.checked.set(row.selected);
    this.toggleRow(row.id, event.shiftKey);
  }

  /** Space on the checkbox toggles it without a click event. */
  protected onSelectCellKeydown(row: RowView<T>, box: KoCheckbox, event: KeyboardEvent): void {
    if (event.key !== " ") return;
    if (!(event.target as Element).closest('button[role="checkbox"]')) return;
    box.checked.set(row.selected);
    this.toggleRow(row.id, event.shiftKey);
  }

  /** Shift+mousedown would otherwise extend the page's text selection. */
  protected preventShiftSelect(event: MouseEvent): void {
    if (event.shiftKey) event.preventDefault();
  }

  private toggleRow(id: string, shiftKey: boolean): void {
    const selected = this.selection();
    if (!selected) return;
    const next =
      shiftKey && this.anchor != null
        ? selectRange(
            selected,
            this.sortedRows().map((r) => r.id),
            this.anchor,
            id,
          )
        : toggleSelection(selected, id);
    this.anchor = id;
    this.selectionChange.emit(next);
  }
}

@if (loading()) {
  <div [class]="class()">
    <div class="flex items-center justify-center gap-2 py-6 text-sm text-muted-foreground">
      <ng-icon aria-hidden="true" size="1rem" class="animate-spin" [svg]="spinner" />
      Loading…
    </div>
  </div>
} @else if (emptyAlone()) {
  <div [class]="class()">
    <ng-container [ngTemplateOutlet]="empty()?.template ?? null" />
  </div>
} @else if (showCards()) {
  <div [class]="class()">
    @if (classNames()?.mobileList; as mobileList) {
      <div [class]="mobileList">
        <ng-container [ngTemplateOutlet]="cards" />
      </div>
    } @else {
      <ng-container [ngTemplateOutlet]="cards" />
    }
  </div>
} @else if (needsWrapper()) {
  <!-- Only add a scroll container when something needs one; a plain auto-layout table with no class renders bare. -->
  <div [class]="wrapperClass()">
    <ng-container [ngTemplateOutlet]="tableView" />
  </div>
} @else {
  <ng-container [ngTemplateOutlet]="tableView" />
}

<ng-template #cards>
  @for (row of sortedRows(); track row.id) {
    <ng-container
      [ngTemplateOutlet]="mobileCard()?.template ?? null"
      [ngTemplateOutletContext]="{ $implicit: row.original }"
    />
  }
</ng-template>

<ng-template #tableView>
  <table
    [class]="classNames()?.table ?? ''"
    [style.width.px]="fixed() ? totalWidth() : null"
    [style.table-layout]="fixed() ? 'fixed' : null"
  >
    @if (fixed()) {
      <colgroup>
        @for (header of headers(); track header.id) {
          <col [style.width.px]="header.size" />
        }
      </colgroup>
    }
    <thead [class]="classNames()?.thead ?? ''">
      <tr [class]="classNames()?.headerRow ?? ''">
        @for (header of headers(); track header.id) {
          @if (header.select) {
            <th [class]="header.className" [style.left.px]="header.left">
              <ko-checkbox
                #all
                aria-label="Select all rows"
                class="align-middle"
                [disabled]="rows().length === 0"
                [checked]="headerChecked()"
                (checkedChange)="onToggleAll(all)"
              />
            </th>
          } @else {
            <th
              [class]="header.className"
              [style.left.px]="header.left"
              [attr.aria-sort]="header.ariaSort"
            >
              @if (header.sortable) {
                <button
                  type="button"
                  [class]="
                    header.column.align === 'right'
                      ? 'inline-flex cursor-pointer flex-row-reverse items-center gap-1 hover:text-foreground'
                      : 'inline-flex cursor-pointer items-center gap-1 hover:text-foreground'
                  "
                  (click)="header.toggleSort?.($event)"
                >
                  <ng-container
                    [ngTemplateOutlet]="headerContent"
                    [ngTemplateOutletContext]="{ $implicit: header }"
                  />
                  @if (header.sorted === "asc") {
                    <ng-icon aria-hidden="true" size="0.75rem" [svg]="arrowUp" />
                  } @else if (header.sorted === "desc") {
                    <ng-icon aria-hidden="true" size="0.75rem" [svg]="arrowDown" />
                  }
                </button>
              } @else {
                <ng-container
                  [ngTemplateOutlet]="headerContent"
                  [ngTemplateOutletContext]="{ $implicit: header }"
                />
              }
              @if (header.showHandle) {
                <ko-resize-handle
                  [width]="header.size"
                  [minSize]="header.minSize"
                  [maxSize]="header.maxSize"
                  [label]="header.label"
                  (widthChange)="setWidth(header.column.id, $event)"
                  (widthReset)="resetWidth(header.column.id)"
                />
              }
            </th>
          }
        }
      </tr>
    </thead>
    <tbody>
      @for (row of bodyRows(); track row.id) {
        <tr
          [class]="row.className"
          [attr.data-selected]="row.selected ? 'true' : null"
          (click)="onRowClick(row.original, $event)"
          (dblclick)="onRowDoubleClick(row.original, $event)"
          (contextmenu)="onRowContextMenu(row.original, $event)"
        >
          @for (cell of row.cells; track cell.id) {
            @if (cell.select) {
              <td
                data-grid-select
                [class]="cell.className"
                [style.left.px]="cell.left"
                (click)="onSelectCellClick(row, box, $event)"
                (keydown)="onSelectCellKeydown(row, box, $event)"
                (mousedown)="preventShiftSelect($event)"
              >
                <ko-checkbox
                  #box
                  class="align-middle"
                  [aria-label]="rowLabel(row)"
                  [checked]="row.selected"
                />
              </td>
            } @else {
              <td [class]="cell.className" [style.left.px]="cell.left" [attr.title]="cell.title">
                <ng-template [flexRender]="cell.cell" [flexRenderProps]="row.original" let-value>{{
                  value
                }}</ng-template>
              </td>
            }
          }
        </tr>
        @if (row.detail) {
          <tr [class]="classNames()?.detailRow ?? ''">
            <td [attr.colspan]="headers().length" [class]="classNames()?.detailCell ?? ''">
              <ng-container
                [ngTemplateOutlet]="rowDetail()?.template ?? null"
                [ngTemplateOutletContext]="{ $implicit: row.original }"
              />
            </td>
          </tr>
        }
      }
      @if (emptyInBody()) {
        <tr [class]="classNames()?.emptyRow ?? ''">
          <td [attr.colspan]="headers().length" [class]="classNames()?.emptyCell ?? ''">
            <ng-container [ngTemplateOutlet]="empty()?.template ?? null" />
          </td>
        </tr>
      }
    </tbody>
  </table>
</ng-template>

<ng-template #headerContent let-header>
  @if (header.text !== null) {
    {{ header.text }}
  } @else {
    <ng-container [ngTemplateOutlet]="header.template" />
  }
</ng-template>

